import datetime

def validate_user_data(name, age_str, email):
    """Validate user data and raise ValueError for any invalid fields."""
    # Validate name
    if not name or not isinstance(name, str):
        raise ValueError("Name must be a non-empty string")

    # Validate age
    try:
        age = int(age_str)
    except ValueError:
        raise ValueError(f"Age must be a number, got '{age_str}'")

    if age < 18:
        raise ValueError(f"Age must be 18 or older, got {age}")
    if age > 120:
        raise ValueError(f"Age seems unrealistic: {age}")

    # Validate email
    if not email or '@' not in email:
        raise ValueError("Email must contain '@' character")

    return name, age, email

# Main processing logic
valid_users = []
errors = []

try:
    with open('users.txt', 'r') as file:
        for line_num, line in enumerate(file, 1):
            line = line.strip()
            if not line:  # Skip empty lines
                continue

            try:
                parts = line.split(',')
                if len(parts) != 3:
                    raise ValueError(f"Expected 3 comma-separated values, got {len(parts)}")

                name, age, email = validate_user_data(parts[0].strip(), parts[1].strip(), parts[2].strip())
                valid_users.append((name, age, email))

            except ValueError as e:
                errors.append(f"Line {line_num}: {e}")
                # Log to error file
                with open('error_log.txt', 'a') as error_file:
                    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    error_file.write(f"[{timestamp}] Line {line_num}: {e} - Data: {line}\n")

except FileNotFoundError:
    errors.append("CRITICAL: users.txt file not found")
    with open('error_log.txt', 'a') as error_file:
        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        error_file.write(f"[{timestamp}] FileNotFoundError: users.txt not found\n")

# Generate report
try:
    with open('user_report.txt', 'w') as report_file:
        report_file.write("=== USER DATA PROCESSING REPORT ===\n")
        report_file.write(f"Total lines processed: {len(valid_users) + len(errors)}\n")
        report_file.write(f"Successfully processed: {len(valid_users)} users\n")
        report_file.write(f"Failed to process: {len(errors)} lines\n\n")

        if valid_users:
            report_file.write("VALID USERS:\n")
            for name, age, email in valid_users:
                report_file.write(f"- {name} ({age}): {email}\n")

        if errors:
            report_file.write("\nERROR SUMMARY:\n")
            for error in errors:
                report_file.write(f"- {error}\n")

        print("Report generated: user_report.txt")

except Exception as e:
    print(f"Failed to generate report: {e}")
